using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, L;
    cin >> N >> M >> L;
    vector<int> S(M + 1);
    for (int i = 1; i <= M; i++) cin >> S[i];
    vector<int> pref(M + 1, 0);
    for (int i = 1; i <= M; i++) pref[i] = pref[i-1] + S[i];

    // cost[a][b] for a <= b
    vector<vector<int>> cost(M + 1, vector<int>(M + 1, 0));
    for (int a = 1; a <= M; a++) {
        for (int b = a; b <= M; b++) {
            cost[a][b] = (pref[b] - pref[a-1]) / L;
        }
    }

    const int INF = 1e9;
    int ans = INF;

    // Fix first note as f, then DP for remaining N-1 notes
    for (int first = 1; first <= M; first++) {
        // dp[i][p] = min energy for first i notes ending with pitch p
        vector<vector<int>> dp(N, vector<int>(M + 1, INF));
        dp[0][first] = 0;
        for (int i = 1; i < N; i++) {
            for (int prev = 1; prev <= M; prev++) {
                if (dp[i-1][prev] == INF) continue;
                for (int cur = 1; cur <= M; cur++) {
                    int a = min(prev, cur);
                    int b = max(prev, cur);
                    int add = cost[a][b];
                    dp[i][cur] = min(dp[i][cur], dp[i-1][prev] + add);
                }
            }
        }
        // Close the circle: last note to first note
        for (int last = 1; last <= M; last++) {
            if (dp[N-1][last] == INF) continue;
            int a = min(last, first);
            int b = max(last, first);
            int total = dp[N-1][last] + cost[a][b];
            ans = min(ans, total);
        }
    }

    cout << ans << "\n";
    return 0;
}

