int main() {
    int N, M, L;
    cin >> N >> M >> L;

    vector<long long> S(M+1);
    for (int i = 1; i <= M; i++) cin >> S[i];

    vector<int> K(N);
    for (int i = 0; i < N; i++) cin >> K[i];

    // Prefix sums
    vector<long long> pre(M+2, 0);
    for (int i = 1; i <= M; i++) pre[i] = pre[i-1] + S[i];

    // Cost between notes i and j
    auto cost = [&](int i, int j) -> long long {
        int a = K[i], b = K[j];
        if (a > b) swap(a, b);
        return (pre[b] - pre[a-1]) / L;
    };

    // TSP with bitmask DP
    int full = (1 << N) - 1;
    vector<vector<long long>> dp(1 << N, vector<long long>(N, LLONG_MAX / 2));
    dp[1][0] = 0; // start at node 0

    for (int mask = 1; mask <= full; mask++) {
        for (int u = 0; u < N; u++) {
            if (!(mask & (1 << u))) continue;
            if (dp[mask][u] == LLONG_MAX / 2) continue;
            for (int v = 0; v < N; v++) {
                if (mask & (1 << v)) continue;
                int nmask = mask | (1 << v);
                long long nc = dp[mask][u] + cost(u, v);
                if (nc < dp[nmask][v]) dp[nmask][v] = nc;
            }
        }
    }

    long long ans = LLONG_MAX / 2;
    for (int u = 1; u < N; u++) {
        ans = min(ans, dp[full][u] + cost(u, 0));
    }

    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    long long L;
    cin >> N >> M >> L;

    vector<long long> S(M + 1), pref(M + 1, 0);
    for (int i = 1; i <= M; ++i) {
        cin >> S[i];
        pref[i] = pref[i - 1] + S[i];
    }

    vector<int> K(N);
    for (int i = 0; i < N; ++i) cin >> K[i];

    vector<long long> cnt(M + 1, 0);
    for (int x : K) cnt[x]++;

    vector<int> vals;
    for (int i = 1; i <= M; ++i) {
        if (cnt[i] > 0) vals.push_back(i);
    }

    int D = (int)vals.size();

    // If only one distinct pitch exists, every adjacent pair is identical.
    if (D == 1) {
        int x = vals[0];
        long long w = (pref[x] - pref[x - 1]) / L; // = S[x] / L
        cout << (long long)N * w << '\n';
        return 0;
    }

    auto cost = [&](int a, int b) -> long long {
        if (a > b) swap(a, b);
        return (pref[b] - pref[a - 1]) / L;
    };

    // Build complete graph on distinct pitches with edge weights = repulsive force.
    // We need a minimum Hamiltonian cycle in a complete graph where each vertex i
    // must appear cnt[i] times consecutively merged. Since w(i,i) <= w(i,j),
    // duplicates of the same pitch should be placed contiguously, contributing
    // (cnt[i]-1)*w(i,i). Then we only need to find the minimum cycle over distinct pitches.
    long long base = 0;
    for (int v : vals) {
        base += (cnt[v] - 1) * cost(v, v);
    }

    // Interval DP on sorted distinct pitches.
    // dp[l][r][0/1]: minimum path cost visiting vals[l..r] exactly once,
    // ending at vals[l] (0) or vals[r] (1).
    const long long INF = (1LL << 62);
    vector<vector<array<long long,2>>> dp(D, vector<array<long long,2>>(D, {INF, INF}));

    for (int i = 0; i < D; ++i) {
        dp[i][i][0] = dp[i][i][1] = 0;
    }

    for (int len = 2; len <= D; ++len) {
        for (int l = 0; l + len - 1 < D; ++l) {
            int r = l + len - 1;

            // end at l
            dp[l][r][0] = min(
                dp[l + 1][r][0] + cost(vals[l + 1], vals[l]),
                dp[l + 1][r][1] + cost(vals[r], vals[l])
            );

            // end at r
            dp[l][r][1] = min(
                dp[l][r - 1][0] + cost(vals[l], vals[r]),
                dp[l][r - 1][1] + cost(vals[r - 1], vals[r])
            );
        }
    }

    long long ansCycle = INF;
    // Close the Hamiltonian path into a cycle.
    ansCycle = min(ansCycle, dp[0][D - 1][0] + cost(vals[0], vals[D - 1]));
    ansCycle = min(ansCycle, dp[0][D - 1][1] + cost(vals[0], vals[D - 1]));

    cout << base + ansCycle << '\n';
    return 0;
}

