public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int L = Integer.parseInt(st.nextToken());

        int[] S = new int[M + 1];
        st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= M; i++) {
            S[i] = Integer.parseInt(st.nextToken());
        }

        int[] K = new int[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            K[i] = Integer.parseInt(st.nextToken());
        }

        // Precompute prefix sum of S for fast interval sum
        long[] prefix = new long[M + 1];
        for (int i = 1; i <= M; i++) {
            prefix[i] = prefix[i - 1] + S[i];
        }

        // Function to compute cost between two pitches a and b (a <= b)
        // cost = floor((S_a + ... + S_b) / L)
        long[][] cost = new long[M + 1][M + 1];
        for (int a = 1; a <= M; a++) {
            for (int b = a; b <= M; b++) {
                long sum = prefix[b] - prefix[a - 1];
                cost[a][b] = sum / L;
            }
        }

        // Sort pitches
        Arrays.sort(K);

        // For N = 1, there is no adjacent pair (circular with 1 element has no edges)
        if (N == 1) {
            System.out.println(0);
            return;
        }

        // For N = 2, only one pair (both directions but same)
        if (N == 2) {
            int a = K[0];
            int b = K[1];
            if (a > b) { int t = a; a = b; b = t; }
            System.out.println(cost[a][b]);
            return;
        }

        // For N >= 3: place in sorted order around the circle.
        // Adjacent pairs: (K[0],K[1]), (K[1],K[2]), ..., (K[N-2],K[N-1]), (K[N-1],K[0])
        long total = 0;
        for (int i = 0; i < N - 1; i++) {
            int a = K[i];
            int b = K[i + 1];
            if (a > b) { int t = a; a = b; b = t; }
            total += cost[a][b];
        }
        // last pair: K[N-1] and K[0]
        int a = K[N - 1];
        int b = K[0];
        if (a > b) { int t = a; a = b; b = t; }
        total += cost[a][b];

        System.out.println(total);
    }
}

