        long[] S = new long[M + 1];
        for (int i = 1; i <= M; i++) S[i] = sc.nextLong();
        int[] K = new int[N];
        for (int i = 0; i < N; i++) K[i] = sc.nextInt();

        long[] prefix = new long[M + 1];
        for (int i = 1; i <= M; i++) prefix[i] = prefix[i-1] + S[i];

        // cost between pitch a and b
        // repulsive = floor((S_min...S_max) / L)
        long cost[][] = new long[N][N];
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++) {
                int a = Math.min(K[i], K[j]), b = Math.max(K[i], K[j]);
                cost[i][j] = (prefix[b] - prefix[a-1]) / L;
            }

        // TSP DP
        long[][] dp = new long[1<<N][N];
        for (long[] row : dp) Arrays.fill(row, Long.MAX_VALUE/2);
        dp[1][0] = 0;
        for (int mask = 1; mask < (1<<N); mask++)
            for (int last = 0; last < N; last++) {
                if ((mask & (1<<last)) == 0 || dp[mask][last] >= Long.MAX_VALUE/2) continue;
                for (int next = 0; next < N; next++) {
                    if ((mask & (1<<next)) != 0) continue;
                    int nmask = mask | (1<<next);
                    dp[nmask][next] = Math.min(dp[nmask][next], dp[mask][last] + cost[last][next]);
                }
            }
        long ans = Long.MAX_VALUE;
        int full = (1<<N)-1;
        for (int last = 1; last < N; last++)
            ans = Math.min(ans, dp[full][last] + cost[last][0]);
        System.out.println(ans);
    }
}

