public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int M = fs.nextInt();
        long L = fs.nextLong();

        long[] S = new long[M + 1];
        long[] pref = new long[M + 1];
        for (int i = 1; i <= M; i++) {
            S[i] = fs.nextLong();
            pref[i] = pref[i - 1] + S[i];
        }

        long[] cnt = new long[M + 1];
        for (int i = 0; i < N; i++) {
            int k = fs.nextInt();
            cnt[k]++;
        }

        // cost[a][b] for a<=b is floor((sum S[a..b]) / L)
        // Since all notes with same pitch are identical, only counts matter.
        //
        // Let w(i,j)=cost[min(i,j)][max(i,j)].
        // We need minimum Hamiltonian cycle cost on a multiset arranged on a line of pitch values.
        //
        // Because w is an interval cost on ordered values, an optimal circular arrangement
        // can be transformed into a "pendulum" order, and the minimum total cost equals:
        // 2 * sum over gaps crossed by adjacency pairs count, which is minimized by using
        // each pitch block contiguously and arranging blocks in monotone circular order.
        //
        // Then only adjacent distinct pitch values in the chosen circular order matter.
        // On a circle over ordered pitches with existing counts, the optimal order is the natural order.
        // Total = internal edges + boundary edges.
        //
        // Internal edges for same pitch i: cnt[i]-1 edges each with w(i,i)=floor(S[i]/L)
        // Boundary edges between consecutive existing pitches in circular order: one edge each,
        // plus one closing edge between first and last.
        //
        // This is optimal by uncrossing on line metric induced by interval sums.

        ArrayList<Integer> vals = new ArrayList<>();
        for (int i = 1; i <= M; i++) if (cnt[i] > 0) vals.add(i);

        if (vals.size() == 1) {
            int v = vals.get(0);
            long same = S[v] / L;
            System.out.println(same * N);
            return;
        }

        long ans = 0;

        for (int v : vals) {
            long same = S[v] / L;
            ans += (cnt[v] - 1) * same;
        }

        for (int i = 0; i + 1 < vals.size(); i++) {
            int a = vals.get(i), b = vals.get(i + 1);
            ans += (pref[b] - pref[a - 1]) / L;
        }

        int first = vals.get(0);
        int last = vals.get(vals.size() - 1);
        ans += (pref[last] - pref[first - 1]) / L;

        System.out.println(ans);
    }
}

