static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N, M;
    ll L;
    if (scanf("%d %d %lld", &N, &M, &L) != 3) return 0;

    ll *S = (ll*)malloc((M + 1) * sizeof(ll));
    ll *pref = (ll*)malloc((M + 1) * sizeof(ll));
    for (int i = 1; i <= M; i++) scanf("%lld", &S[i]);

    pref[0] = 0;
    for (int i = 1; i <= M; i++) pref[i] = pref[i - 1] + S[i];

    int *cnt = (int*)calloc(M + 1, sizeof(int));
    for (int i = 0; i < N; i++) {
        int k;
        scanf("%d", &k);
        cnt[k]++;
    }

    /* Distinct pitches present */
    int D = 0;
    for (int i = 1; i <= M; i++) if (cnt[i] > 0) D++;

    if (D == 1) {
        printf("0\n");
        free(S); free(pref); free(cnt);
        return 0;
    }

    int *p = (int*)malloc(D * sizeof(int));
    int idx = 0;
    for (int i = 1; i <= M; i++) if (cnt[i] > 0) p[idx++] = i;

    /*
      Let w(a,b) = floor((sum_{min(a,b)}^{max(a,b)} S)/L).
      Since all S_i > 0, w satisfies Monge on sorted pitches.
      The optimal circular arrangement is obtained by splitting the sorted multiset
      into two monotone chains and alternating them around the circle, which yields:
      answer = 2 * sum_{i=1}^{D-1} w(p_i, p_{i+1}) - max removable edge
      where removable edge corresponds to one adjacent pair in the path after doubling.
      This simplifies to:
      answer = 2 * sum consecutive - max over i of (w(p_i,p_{i+1}) + extra endpoint handling),
      and for multiplicities, duplicates can be placed consecutively at zero cost.
      Eventually the minimum for distinct sorted values is:
      2 * sum_{i=0}^{D-2} w(p[i],p[i+1]) - max_{0<=i<D-1} w(p[i],p[i+1])
      - min endpoint correction = actually equivalent to
      sum consecutive + sum consecutive - largest consecutive,
      because closing the circle can use the largest gap once instead of twice.
      Thus:
      ans = 2*sum(consecutive costs) - max(consecutive cost).
    */

    ll sum = 0, mx = 0;
    for (int i = 0; i < D - 1; i++) {
        int a = p[i], b = p[i + 1];
        ll cost = (pref[b] - pref[a - 1]) / L;
        sum += cost;
        if (cost > mx) mx = cost;
    }

    ll ans = 2 * sum - mx;
    printf("%lld\n", ans);

    free(S);
    free(pref);
    free(cnt);
    free(p);
    return 0;
}

import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    L = int(next(it))
    S = [0] + [int(next(it)) for _ in range(M)]

    # Prefix sum for fast range sum
    pref = [0] * (M + 1)
    for i in range(1, M + 1):
        pref[i] = pref[i-1] + S[i]

    # repulsive force between a and b (1-indexed, a ≤ b)
    def rep(a, b):
        return (pref[b] - pref[a-1]) // L

    # cost[i][j] for 1-indexed pitches
    cost = [[0] * (M+1) for _ in range(M+1)]
    for a in range(1, M+1):
        for b in range(a, M+1):
            cost[a][b] = rep(a, b)

    INF = 10**18

    # Fix first note = k
    ans = INF
    for first in range(1, M+1):
        # dp[i][j] = min cost for sequence of length j ending with pitch i
        dp = [[INF] * (N+1) for _ in range(M+1)]
        dp[first][1] = 0
        for length in range(1, N):
            for last in range(1, M+1):
                if dp[last][length] == INF:
                    continue
                for nxt in range(1, M+1):
                    a = min(last, nxt)
                    b = max(last, nxt)
                    new_cost = dp[last][length] + cost[a][b]
                    if new_cost < dp[nxt][length+1]:
                        dp[nxt][length+1] = new_cost
        # close the circle
        for last in range(1, M+1):
            if dp[last][N] == INF:
                continue
            a = min(last, first)
            b = max(last, first)
            total = dp[last][N] + cost[a][b]
            if total < ans:
                ans = total

    print(ans)

if __name__ == "__main__":
    solve()

import sys
from itertools import combinations

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N = int(input_data[idx]); idx+=1
    M = int(input_data[idx]); idx+=1
    L = int(input_data[idx]); idx+=1
    S = [int(input_data[idx+i]) for i in range(M)]; idx+=M
    K = [int(input_data[idx+i]) for i in range(N)]; idx+=N

    # prefix sums (1-indexed)
    prefix = [0] * (M+1)
    for i in range(1, M+1):
        prefix[i] = prefix[i-1] + S[i-1]

    def cost(a, b):
        # pitches a, b (1-indexed), a <= b
        if a > b:
            a, b = b, a
        return (prefix[b] - prefix[a-1]) // L

    # Build cost matrix between notes (by index)
    # K[i] is pitch of note i (0-indexed)
    c = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if i != j:
                c[i][j] = cost(K[i], K[j])

    if N == 1:
        print(0)
        return

    # TSP bitmask DP
    INF = float('inf')
    dp = [[INF]*N for _ in range(1<<N)]
    dp[1][0] = 0  # start at node 0

    for mask in range(1<<N):
        for u in range(N):
            if dp[mask][u] == INF:
                continue
            if not (mask >> u & 1):
                continue
            for v in range(N):
                if mask >> v & 1:
                    continue
                nmask = mask | (1<<v)
                val = dp[mask][u] + c[u][v]
                if val < dp[nmask][v]:
                    dp[nmask][v] = val

    full = (1<<N) - 1
    ans = INF
    for u in range(1, N):
        if dp[full][u] != INF:
            ans = min(ans, dp[full][u] + c[u][0])

    print(ans)

